def settings(tmp_path):
    return AppSettings(
        skill_root=tmp_path,
        data_dir=tmp_path / "data",
        profile_path=tmp_path / "profile.yaml",
        repo_roots=[],
    )


def card(status: CardStatus, revision: int) -> EvidenceCard:
    sources = []
    if status is CardStatus.SUPPORTED:
        sources = [
            EvidenceSource(
                lane=RetrievalLane.RIPGREP,
                label="live-evidence-proof/remove_invalid_parentheses.py",
                excerpt="def remove_invalid_parentheses(text: str) -> str:",
                score=0.9,
                freshness=Freshness.CURRENT,
                path="/tmp/live-evidence-proof/remove_invalid_parentheses.py",
                repository="live-evidence-proof",
            )
        ]
    return EvidenceCard(
        query=f"revision {revision}",
        thread="parentheses",
        talking_point="supported" if sources else "No source-bound support surfaced yet.",
        proof="source proof" if sources else "No source-bound support surfaced yet.",
        qualifier="bounded",
        confidence=0.8 if sources else 0.0,
        status=status,
        sources=sources,
        lanes=[RetrievalLane.RIPGREP] if sources else [],
        question_id="question-1234",
        question_revision=revision,
    )


