async def _assert_later_insufficient_revision_does_not_evict_supported_card(tmp_path) -> None:
    state = RuntimeState(settings(tmp_path), InterviewProfile(name="state-test"))
    await state.start_session(consent_confirmed=True)
    question_id, _ = await state.revise_question("remove minimum invalid parentheses")

    supported = card(CardStatus.SUPPORTED, revision=1).model_copy(
        update={"question_id": question_id}
    )
    assert await state.publish_card_fenced(supported) is not None

    # Simulate cumulative STT creating weaker later revisions before the
    # resolver decides they are incomplete fragments.
    await state.revise_question("opening parenthesis comes before closing")
    await state.revise_question("incomplete trailing explanation")
    insufficient = card(CardStatus.INSUFFICIENT, revision=3).model_copy(
        update={"question_id": question_id}
    )

    assert await state.publish_card_fenced(insufficient) is None
    snapshot = await state.snapshot()

    assert len(snapshot.cards) == 1
    assert snapshot.cards[0].status is CardStatus.SUPPORTED
    assert snapshot.cards[0].question_revision == 1
    assert snapshot.cards[0].sources[0].path.endswith("remove_invalid_parentheses.py")


async def _assert_publication_reducer_records_visible_decision(tmp_path) -> None:
    state = RuntimeState(settings(tmp_path), InterviewProfile(name="state-test"))
    await state.start_session(consent_confirmed=True)
    question_id, revision = await state.revise_question("remove minimum invalid parentheses")

    supported = card(CardStatus.SUPPORTED, revision=revision).model_copy(
        update={"question_id": question_id}
    )
    assert await state.publish_card_fenced(supported) is not None

    decisions = await state.card_publication_journal()
    decision = decisions[-1]
    assert decision.status is PublicationStatus.VISIBLE
    assert decision.question_id == question_id
    assert decision.question_revision == revision
    assert decision.answer_revision == revision
    assert decision.transcript_refs == [f"question:{question_id}:revision:{revision}"]
    assert decision.source_refs
    assert decision.rank_components["source_count"] == 1
    assert decision.visible_card_ids == [supported.card_id]


async def _assert_malformed_supported_card_is_held_with_reason(tmp_path) -> None:
    state = RuntimeState(settings(tmp_path), InterviewProfile(name="state-test"))
    await state.start_session(consent_confirmed=True)
    question_id, revision = await state.revise_question("remove minimum invalid parentheses")

    malformed = card(CardStatus.SUPPORTED, revision=revision).model_copy(
        update={"question_id": question_id, "sources": []}
    )
    assert await state.publish_card_fenced(malformed) is None

    snapshot = await state.snapshot()
    decisions = await state.card_publication_journal()
    assert snapshot.cards == []
    assert decisions[-1].status is PublicationStatus.HELD
    assert decisions[-1].reason_codes == ["supported_card_missing_sources"]


async def _assert_stale_same_question_revision_is_superseded(tmp_path) -> None:
    state = RuntimeState(settings(tmp_path), InterviewProfile(name="state-test"))
    await state.start_session(consent_confirmed=True)
    question_id, _ = await state.revise_question("remove minimum invalid parentheses")
    await state.revise_question("remove minimum invalid parentheses with stack")

    current = card(CardStatus.SUPPORTED, revision=2).model_copy(
        update={"question_id": question_id}
    )
    stale = card(CardStatus.SUPPORTED, revision=1).model_copy(
        update={"question_id": question_id}
    )
    assert await state.publish_card_fenced(current) is not None
    assert await state.publish_card_fenced(stale) is None

    snapshot = await state.snapshot()
    decisions = await state.card_publication_journal()
    assert [item.card_id for item in snapshot.cards] == [current.card_id]
    assert decisions[-1].status is PublicationStatus.SUPERSEDED
    assert decisions[-1].reason_codes == ["stale_revision_blocked_by_newer_visible_card"]
    assert decisions[-1].visible_card_ids == [current.card_id]


async def _assert_duplicate_current_question_reconciles_to_one_visible_card(tmp_path) -> None:
    state = RuntimeState(settings(tmp_path), InterviewProfile(name="state-test"))
    await state.start_session(consent_confirmed=True)
    question_id, revision = await state.revise_question("remove minimum invalid parentheses")

    first = card(CardStatus.SUPPORTED, revision=revision).model_copy(
        update={"question_id": question_id, "answer": "first answer"}
    )
    second = card(CardStatus.SUPPORTED, revision=revision).model_copy(
        update={"question_id": question_id, "answer": "refined answer"}
    )
    assert await state.publish_card_fenced(first) is not None
    assert await state.publish_card_fenced(second) is not None

    snapshot = await state.snapshot()
    decisions = await state.card_publication_journal()
    assert len(snapshot.cards) == 1
    assert snapshot.cards[0].card_id == second.card_id
    assert snapshot.cards[0].answer == "refined answer"
    assert decisions[-1].status is PublicationStatus.VISIBLE
    assert decisions[-1].reason_codes == ["visible_replaces_same_question_card"]


async def _assert_superseded_question_completion_stays_behind_active_card(tmp_path) -> None:
    state = RuntimeState(settings(tmp_path), InterviewProfile(name="state-test"))
    await state.start_session(consent_confirmed=True)

    old_question_id, _ = await state.revise_question(
        "Explain how consistent hashing rebalances keys when a new node joins."
    )
    new_question_id, _ = await state.revise_question(
        "Which HTTP status code should a rate-limited API return?"
    )
    assert old_question_id != new_question_id

    active = card(CardStatus.SUPPORTED, revision=1).model_copy(
        update={
            "question_id": new_question_id,
            "query": "Which HTTP status code should a rate-limited API return?",
        }
    )
    assert await state.publish_card_fenced(active) is not None

    completed_old = card(CardStatus.SUPPORTED, revision=1).model_copy(
        update={
            "question_id": old_question_id,
            "query": "Explain how consistent hashing rebalances keys.",
        }
    )
    assert await state.publish_card_fenced(completed_old) is not None

    snapshot = await state.snapshot()

    assert [item.question_id for item in snapshot.cards[:2]] == [
        new_question_id,
        old_question_id,
    ]
    assert "rate-limited" in snapshot.cards[0].query
    assert "consistent hashing" in snapshot.cards[1].query


